<?php
declare(strict_types=1);
$root=dirname(__DIR__,3);
require $root.'/bootstrap.php';

$target=$root.'/app/Market/Phase7E21AcceptedSafetyGuard.php';
$writer=$root.'/app/Market/StructuredOfferWriter.php';

if(!is_file($writer)){fwrite(STDERR,"ERROR: StructuredOfferWriter.php ontbreekt.\n");exit(1);}

$backup=$root.'/storage/backups/phase7e21-fix2-'.date('Ymd-His');
@mkdir($backup,0775,true);
copy($writer,$backup.'/StructuredOfferWriter.php');
if(is_file($target)) copy($target,$backup.'/Phase7E21AcceptedSafetyGuard.php');

$guard=base64_decode('');
if($guard===false || file_put_contents($target,$guard)===false){
    fwrite(STDERR,"ERROR: FIX2 guard kon niet worden geschreven.\n");exit(1);
}

$writerCode=file_get_contents($writer);
if(!str_contains((string)$writerCode,'LITTYWATCH_PHASE7E21_ACCEPTED_SAFETY')){
    fwrite(STDERR,"ERROR: 7E.21 writer marker ontbreekt.\n");exit(1);
}

echo "OK: LittyWatch V5.2 Phase 7E.21 FIX2 geïnstalleerd.\n";
echo "Backup: {$backup}\n";
echo "Draai nu:\n";
echo "  php -l app/Market/Phase7E21AcceptedSafetyGuard.php\n";
echo "  php -l app/Market/StructuredOfferWriter.php\n";
echo "  php tools/maintenance/phase7e21-fix2/smoke-test.php\n";
